package app

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"regexp"
	"strings"
	"time"
)

const legacyFrontendURL = "https://d2pypzndaqisk.cloudfront.net"

var apiFallbackHosts = []string{
	defaultAPIBase,
	"https://d18ka9rqpfd3lo.cloudfront.net",
	"https://d37n0wjehmw08f.cloudfront.net",
}

func (d *Downloader) apiEndpoint(ctx context.Context) (string, error) {
	d.apiMu.Lock()
	defer d.apiMu.Unlock()
	if d.apiBase != "" {
		return d.apiBase, nil
	}
	configured := strings.TrimRight(firstNonEmpty(d.cfg.APIBase, defaultAPIBase), "/")
	parsed, err := url.Parse(configured)
	if err != nil || !isProviderHTTPMediaURL(configured) {
		return "", errors.New("API 地址无效")
	}
	if !strings.HasSuffix(strings.ToLower(parsed.Hostname()), ".cloudfront.net") {
		d.apiBase = configured
		return configured, nil
	}
	candidates := append([]string{configured}, apiFallbackHosts...)
	seen := map[string]bool{}
	var lastErr error
	for pass := 0; pass < 2; pass++ {
		if pass == 1 {
			candidates, err = d.discoverAPIHosts(ctx)
			if err != nil {
				lastErr = err
				break
			}
		}
		for _, candidate := range candidates {
			if seen[candidate] {
				continue
			}
			seen[candidate] = true
			if err := ctx.Err(); err != nil {
				return "", err
			}
			if err := d.probeAPIHost(ctx, candidate); err != nil {
				lastErr = err
				continue
			}
			d.apiBase = candidate
			return candidate, nil
		}
	}
	return "", fmt.Errorf("黄果原 API 的候选域名均不可用: %w", publicError(lastErr))
}

func (d *Downloader) resetAPIEndpoint(failed string) {
	d.apiMu.Lock()
	if d.apiBase == failed {
		d.apiBase = ""
	}
	d.apiMu.Unlock()
}

func (d *Downloader) probeAPIHost(ctx context.Context, host string) error {
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, host+"/api/app/ping/check", nil)
	if err != nil {
		return err
	}
	request.Header.Set("User-Agent", userAgent)
	response, err := d.doCatalogRequestWithTimeout(request, 4*time.Second)
	if err != nil {
		return publicError(err)
	}
	defer response.Body.Close()
	var envelope struct {
		Code int `json:"code"`
	}
	if response.StatusCode != http.StatusOK || json.NewDecoder(io.LimitReader(response.Body, 64*1024)).Decode(&envelope) != nil || envelope.Code != 200 {
		return fmt.Errorf("%s API 健康检查失败 (HTTP %d)", request.URL.Hostname(), response.StatusCode)
	}
	return nil
}

func (d *Downloader) discoverAPIHosts(ctx context.Context) ([]string, error) {
	body, err := d.fetchLegacyFrontendScript(ctx)
	if err != nil {
		return nil, err
	}
	if hosts := parseAPIHosts(body); len(hosts) > 0 {
		return hosts, nil
	}
	return nil, errors.New("官网前端未提供可识别的 API 地址，请更新 apiBase 配置")
}

func (d *Downloader) fetchLegacyFrontendScript(ctx context.Context) (string, error) {
	page, err := d.fetchProviderText(ctx, legacyFrontendURL+"/", legacyFrontendURL+"/")
	if err != nil {
		return "", err
	}
	scripts := regexp.MustCompile(`(?i)<script\b[^>]*\bsrc=["']([^"']+)["']`).FindAllStringSubmatch(page, -1)
	for _, script := range scripts {
		if !strings.Contains(script[1], "/main-") || !strings.HasSuffix(script[1], ".js") {
			continue
		}
		assetURL := resolveProviderURL(legacyFrontendURL+"/", script[1])
		asset, err := url.Parse(assetURL)
		if err != nil || asset.Hostname() != mustHost(legacyFrontendURL) {
			continue
		}
		body, err := d.fetchProviderText(ctx, assetURL, legacyFrontendURL+"/")
		if err != nil {
			return "", err
		}
		return body, nil
	}
	return "", errors.New("黄果官网未提供可识别的接口脚本")
}

func parseAPIHosts(script string) []string {
	matches := regexp.MustCompile(`https://[a-z0-9]+\.cloudfront\.net`).FindAllString(script, -1)
	seen := map[string]bool{}
	var hosts []string
	for _, host := range matches {
		if host != legacyFrontendURL && !seen[host] {
			seen[host] = true
			hosts = append(hosts, host)
			if len(hosts) == 8 {
				break
			}
		}
	}
	return hosts
}
package app

import (
	"context"
	"errors"
	"fmt"
	"net/url"
	"sort"
	"strings"
	"time"
)

func (d *Downloader) fetchAllDramas(ctx context.Context, sourceFilter string) ([]Drama, error) {
	if more, _ := ctx.Value(libraryMoreKey{}).(bool); more {
		return d.fetchMoreLibrary(ctx, sourceFilter)
	}
	fmt.Println("正在获取剧库列表...")
	type result struct {
		name  string
		items []Drama
		err   error
	}
	jobs := []struct {
		name    string
		timeout time.Duration
		fn      func(context.Context) ([]Drama, error)
	}{
		{name: "cloudfront", timeout: 10 * time.Minute, fn: d.fetchCloudFrontDramas},
		{name: sourceHuangguoAI, timeout: 10 * time.Minute, fn: d.fetchHuangguoAIDramas},
		{name: sourceHuangguoVideo, timeout: 10 * time.Minute, fn: d.fetchHuangguoVideoDramas},
		{name: sourceHuangdou, timeout: 10 * time.Minute, fn: d.fetchHuangdouDramas},
		{name: sourceHongguo, timeout: 10 * time.Minute, fn: d.fetchHongguoDramas},
	}
	selectedJobs := jobs[:0]
	for _, job := range jobs {
		if matchesSourceFilter(job.name, sourceFilter) && sourceAllowed(ctx, job.name) {
			selectedJobs = append(selectedJobs, job)
		}
	}
	jobs = selectedJobs
	ch := make(chan result, len(jobs))
	for _, job := range jobs {
		job := job
		go func() {
			jobCtx, cancel := context.WithTimeout(ctx, job.timeout)
			defer cancel()
			items, err := job.fn(jobCtx)
			ch <- result{name: job.name, items: items, err: err}
		}()
	}
	seen := map[string]bool{}
	var unique []Drama
	failures := map[string]error{}
	for range jobs {
		res := <-ch
		if len(res.items) == 0 && res.err == nil && !(res.name == sourceHongguo && hongguoCatalogInitialized(d.hongguoCatalogSnapshot())) {
			res.err = errors.New("未返回可识别的视频数据")
		}
		if res.err != nil {
			msg := fmt.Sprintf("%s 获取失败: %v", res.name, publicError(res.err))
			fmt.Printf("%s\n", msg)
			failures[res.name] = res.err
		}
		reportLibraryProgress(ctx, res.name, res.items, res.err, true)
		for _, item := range res.items {
			if item.ID == "" || seen[item.ID] {
				continue
			}
			seen[item.ID] = true
			unique = append(unique, item)
		}
	}
	sort.SliceStable(unique, func(i, j int) bool { return unique[i].DisplayTitle() < unique[j].DisplayTitle() })
	fmt.Printf("本次获取剧库：%d 部，结果将合并到本地缓存\n", len(unique))
	if len(failures) > 0 {
		return unique, &libraryLoadError{failures: failures}
	}
	return unique, nil
}

func (d *Downloader) GetDramaChapters(ctx context.Context, seriesID string) (string, []Chapter, error) {
	if source, sourceID, ok := splitProviderDramaID(seriesID); ok {
		return d.GetHuangguoChapters(ctx, source, sourceID)
	}
	var detail detailResponse
	if err := d.fetchAPI(ctx, "/api/app/playlet/detail/"+url.PathEscape(seriesID), nil, &detail); err != nil {
		return "", nil, err
	}
	chapters := detail.Chapters
	if len(chapters) == 0 {
		var list []Chapter
		if err := d.fetchAPI(ctx, "/api/app/playlet-chapter/list/"+url.PathEscape(seriesID), nil, &list); err != nil {
			return "", nil, err
		}
		chapters = list
	}
	title := detail.Title
	if title == "" {
		title = detail.Name
	}
	if title == "" {
		title = "短剧"
	}
	return title, uniqueChapters(chapters), nil
}

func uniqueChapters(chapters []Chapter) []Chapter {
	seen := map[string]bool{}
	var out []Chapter
	for i, ch := range chapters {
		key := ch.ID
		if key == "" {
			key = ch.VideoURL
		}
		if key == "" {
			key = fmt.Sprintf("idx_%d", i)
		}
		if seen[key] {
			continue
		}
		seen[key] = true
		out = append(out, ch)
	}
	return out
}

func (d *Downloader) BuildDramaTasks(ctx context.Context, drama Drama) ([]Task, error) {
	return d.buildDramaTasksInDirectory(ctx, drama, "")
}

func (d *Downloader) buildDramaTasksInDirectory(ctx context.Context, drama Drama, existingDirectory string) ([]Task, error) {
	var title string
	var chapters []Chapter
	var err error
	if isHuangguoProviderSource(drama.Source) {
		sourceID := strings.TrimSpace(drama.SourceID)
		if sourceID == "" {
			if _, parsedID, ok := splitProviderDramaID(drama.ID); ok {
				sourceID = parsedID
			} else {
				sourceID = strings.TrimSpace(drama.ID)
			}
		}
		title, chapters, err = d.GetHuangguoChapters(ctx, drama.Source, sourceID)
	} else {
		title, chapters, err = d.GetDramaChapters(ctx, drama.ID)
	}
	if err != nil {
		return nil, err
	}
	if len(chapters) == 0 {
		return nil, nil
	}
	drama = d.hongguoCachedDrama(drama)
	dramaDir, err := d.downloadDramaDirectory(drama, title, existingDirectory)
	if err != nil {
		return nil, err
	}
	var tasks []Task
	for i, ch := range chapters {
		ep := ch.EpisodeString(i + 1)
		epNum := padEpisode(ep)
		fileName := safeFilename(epNum + ".mp4")
		outPath, err := safeJoin(dramaDir, fileName)
		if err != nil {
			return nil, err
		}
		tasks = append(tasks, Task{DramaID: drama.ID, DramaTitle: title, Chapter: ch, Index: i + 1, Total: len(chapters), OutPath: outPath, ReleaseStatus: dramaReleaseStatus(drama)})
	}
	return tasks, nil
}

