	ctx := request.Context()
	allowed := app.dramaSourcesAllowedLocked(ctx, selection.DramaIDs)
	for _, id := range selection.IDs {
		if task := app.tasks[id]; task != nil && (!dramaAllowed(ctx, task.DramaID, "") || !taskSourceAllowed(ctx, task.Source)) {
			allowed = false
		}
