			if dr.ID == "" {
				continue
			}
			if pos, ok := index[dr.ID]; ok {
				out[pos] = mergeDramaMetadata(out[pos], dr)
				continue
			}
			index[dr.ID] = len(out)
			out = append(out, dr)
		}
	}
	sort.SliceStable(out, func(i, j int) bool { return out[i].DisplayTitle() < out[j].DisplayTitle() })
