package app

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/url"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

type playbackQualityKey struct{}

type playbackQualityOption struct {
	Value int    `json:"value"`
	Label string `json:"label"`
}

var playbackHLSResolution = regexp.MustCompile(`(?:^|,)RESOLUTION=(\d+)x(\d+)(?:,|$)`)

func parsePlaybackQuality(value string) (int, error) {
	if value == "" || value == "auto" {
		return 0, nil
	}
	quality, err := strconv.Atoi(value)
	if err != nil || quality < 0 || quality > 4320 {
		return 0, errors.New("清晰度选项无效")
	}
	return quality, nil
}

func playbackQualityOptions(media providerMedia) []playbackQualityOption {
	options := make([]playbackQualityOption, 0, len(media.Variants))
	seen := make(map[int]bool)
	for _, variant := range media.Variants {
		if variant.Quality <= 0 || variant.Quality > 4320 || seen[variant.Quality] {
			continue
		}
		seen[variant.Quality] = true
		options = append(options, playbackQualityOption{Value: variant.Quality, Label: strconv.Itoa(variant.Quality) + "p"})
	}
	sort.Slice(options, func(i, j int) bool { return options[i].Value > options[j].Value })
	return options
}

func setPlaybackQualityHeaders(header http.Header, media providerMedia) {
	options, _ := json.Marshal(playbackQualityOptions(media))
	header.Set("X-Playback-Qualities", string(options))
	header.Set("X-Playback-Quality", strconv.Itoa(media.Quality))
}

func (downloader *Downloader) selectPlaybackQuality(ctx context.Context, media providerMedia) (providerMedia, error) {
	requested, _ := ctx.Value(playbackQualityKey{}).(int)
	if requested > 0 {
		for _, variant := range media.Variants {
			if variant.Quality == requested {
				variant.Variants = media.Variants
				media = variant
				break
			}
		}
	}
	lines := strings.Split(media.Playlist, "\n")
	variants := playbackHLSVariants(media.Playlist)
	if len(variants) == 0 {
		return media, nil
	}
	sort.SliceStable(variants, func(i, j int) bool { return variants[i].quality > variants[j].quality })
	selected := variants[0]
	media.Variants = nil
	for _, variant := range variants {
		media.Variants = append(media.Variants, providerMedia{Quality: variant.quality})
		if variant.quality == requested {
			selected = variant
		}
	}
	base, err := url.Parse(media.URL)
	if err != nil {
		return providerMedia{}, err
	}
	reference, err := url.Parse(selected.uri)
	if err != nil {
		return providerMedia{}, err
	}
	address := base.ResolveReference(reference).String()
	if !isProviderHTTPMediaURL(address) {
		return providerMedia{}, errors.New("清晰度播放列表地址无效")
	}
	playlist, err := downloader.fetchProviderText(ctx, address, media.Referer)
	if err != nil {
		return providerMedia{}, err
	}
	if !strings.HasPrefix(strings.TrimSpace(strings.TrimPrefix(playlist, "\ufeff")), "#EXTM3U") {
		return providerMedia{}, errors.New("站点未返回所选清晰度的播放列表")
	}
	filtered := make([]string, 0, len(lines))
	for i := 0; i < len(lines); i++ {
		line := strings.TrimSpace(lines[i])
		if strings.HasPrefix(line, "#EXT-X-STREAM-INF:") && i+1 < len(lines) {
			if i == selected.line {
				filtered = append(filtered, lines[i], lines[i+1])
			}
			i++
			continue
		}
		if !strings.HasPrefix(line, "#EXT-X-I-FRAME-STREAM-INF:") {
			filtered = append(filtered, lines[i])
		}
	}
	media.Playlist, media.Quality = strings.Join(filtered, "\n"), selected.quality
	if duration := m3u8Duration(playlist); duration > 0 {
		media.Duration = duration
	}
	return media, nil
}

type playbackHLSVariant struct {
	line    int
	quality int
	uri     string
}

func playbackHLSVariants(playlist string) []playbackHLSVariant {
	lines := strings.Split(playlist, "\n")
	var variants []playbackHLSVariant
	for i := 0; i+1 < len(lines); i++ {
		line := strings.TrimSpace(lines[i])
		if !strings.HasPrefix(line, "#EXT-X-STREAM-INF:") {
			continue
		}
		match := playbackHLSResolution.FindStringSubmatch(strings.TrimPrefix(line, "#EXT-X-STREAM-INF:"))
		if len(match) != 3 {
			continue
		}
		width, _ := strconv.Atoi(match[1])
		height, _ := strconv.Atoi(match[2])
		if width < height {
			height = width
		}
		uri := strings.TrimSpace(lines[i+1])
		if height > 0 && height <= 4320 && uri != "" && !strings.HasPrefix(uri, "#") {
			variants = append(variants, playbackHLSVariant{line: i, quality: height, uri: uri})
		}
	}
	return variants
}
package app

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
)

func readDownloadRequest(writer http.ResponseWriter, request *http.Request) ([]string, *int, bool) {
	var input struct {
		IDs     []string `json:"ids"`
		Quality *int     `json:"quality"`
	}
	decoder := json.NewDecoder(http.MaxBytesReader(writer, request.Body, 1<<20))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&input); err != nil {
		writeJSON(writer, http.StatusBadRequest, map[string]string{"error": "下载参数无效"})
		return nil, nil, false
	}
	if decoder.Decode(new(any)) != io.EOF || input.Quality != nil && (*input.Quality < 0 || *input.Quality > 4320) {
		writeJSON(writer, http.StatusBadRequest, map[string]string{"error": "下载清晰度选项无效"})
		return nil, nil, false
	}
	ids, ok := cleanIDList(writer, input.IDs)
	return ids, input.Quality, ok
}

func preferredDownloadQuality(requested int, available []int) int {
	best, lowest := 0, 0
	for _, quality := range available {
		if quality <= 0 || quality > 4320 {
			continue
		}
		if lowest == 0 || quality < lowest {
			lowest = quality
		}
		if (requested <= 0 || quality <= requested) && quality > best {
			best = quality
		}
	}
	if best == 0 {
		return lowest
	}
	return best
}

func (downloader *Downloader) selectDownloadQuality(ctx context.Context, task Task, media providerMedia) (providerMedia, error) {
	qualities := []int{media.Quality}
	validVariants := make([]providerMedia, 0, len(media.Variants)+1)
	for _, variant := range media.Variants {
		if isProviderHTTPMediaURL(variant.URL) {
			qualities = append(qualities, variant.Quality)
			validVariants = append(validVariants, variant)
		}
	}
	if isProviderHTTPMediaURL(media.URL) {
		current := media
		current.Variants = nil
		validVariants = append(validVariants, current)
	}
	media.Variants = validVariants
	if variants := playbackHLSVariants(media.Playlist); len(variants) > 0 {
		qualities = nil
		for _, variant := range variants {
			qualities = append(qualities, variant.quality)
		}
	}
	quality := preferredDownloadQuality(task.DownloadQuality, qualities)
	selected, err := downloader.selectPlaybackQuality(context.WithValue(ctx, playbackQualityKey{}, quality), media)
	if err != nil {
		return providerMedia{}, err
	}
	var available []int
	for _, option := range playbackQualityOptions(selected) {
		available = append(available, option.Value)
	}
	downloader.recordDiagnostic(diagnosticEvent{Level: "info", Event: "download.media", Source: sourceFromDramaID(task.DramaID),
		DramaID: task.DramaID, DramaTitle: task.DramaTitle, Episode: task.Index, Quality: selected.Quality, RequestedQuality: task.DownloadQuality, AvailableQualities: available,
		Message: "下载保留源媒体的音视频编码和分辨率"})
	return selected, nil
}
package app

import (
	"context"
	"crypto/aes"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"time"
)

var playbackDurationPattern = regexp.MustCompile(`Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)`)
var playbackLevelPattern = regexp.MustCompile(`profile Constrained Baseline, level (\d+)\.(\d+)`)

type playbackLog struct {
	mu       sync.Mutex
	text     cappedStringWriter
	duration float64
	mime     string
	ready    chan struct{}
	once     sync.Once
}

func (log *playbackLog) Write(data []byte) (int, error) {
	log.mu.Lock()
	defer log.mu.Unlock()
	_, _ = log.text.Write(data)
	if log.mime == "" {
		if match := playbackLevelPattern.FindStringSubmatch(log.text.String()); len(match) == 3 {
			major, _ := strconv.Atoi(match[1])
			minor, _ := strconv.Atoi(match[2])
			log.mime = fmt.Sprintf(`video/mp4; codecs="avc1.42C0%02X, mp4a.40.2"`, major*10+minor)
		}
	}
	if log.duration == 0 {
		if match := playbackDurationPattern.FindStringSubmatch(log.text.String()); len(match) == 4 {
			hours, _ := strconv.ParseFloat(match[1], 64)
			minutes, _ := strconv.ParseFloat(match[2], 64)
			seconds, _ := strconv.ParseFloat(match[3], 64)
			log.duration = hours*3600 + minutes*60 + seconds
		}
	}
	if log.mime != "" || strings.Contains(log.text.String(), "Output #0") {
		log.once.Do(func() { close(log.ready) })
	}
	return len(data), nil
}

func (log *playbackLog) snapshot() (float64, string) {
	log.mu.Lock()
	defer log.mu.Unlock()
