		}
		local := proxy.addAsset(asset)
		if local == "" {
			return "", errors.New("HLS 资源数量超过限制")
		}
		return local, nil
	}
	lines := strings.Split(strings.TrimPrefix(raw, "\ufeff"), "\n")
	nextPlaylist := false
