	for _, imported := range imports {
		if len(imported[1]) > 2400 {
			continue
		}
		address := yeguoScriptURL(entry, imported[2])
		if address == "" || seen[address] {
			continue
		}
		if len(seen) >= 20 {
			break
		}
		seen[address] = true
		body, err := d.fetchProviderText(ctx, address, pageURL)
