	setIf(&cfg.HongguoURL, "JUKU_HONGGUO_URL")
	setIf(&cfg.ProxyURL, "JUKU_PROXY_URL")
	setIf(&cfg.OutputDir, "JUKU_OUTPUT_DIR")
	setIf(&cfg.FFmpeg, "JUKU_FFMPEG")
}

