	if _, err := configuredProxy(c.ProxyURL); err != nil {
		return err
	}
	if c.ParamKey != "" && len(c.ParamKey) != aes.BlockSize || c.ParamIV != "" && len(c.ParamIV) != aes.BlockSize {
