package app

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"strings"
	"sync"
	"time"
)

type providerCatalogCursor struct {
	Page int `json:"page"`
	Initialized bool `json:"initialized"`
	Exhausted bool `json:"exhausted"`
	Signature string `json:"signature,omitempty"`
	UpdatedAt time.Time `json:"updatedAt"`
}

type providerCatalogFeed struct {
	loading sync.Mutex
	cursor providerCatalogCursor
}

type providerCatalogStore struct {
	mu sync.Mutex
	feeds map[string]*providerCatalogFeed
}

func cloneProviderCatalog(cursors map[string]providerCatalogCursor) map[string]providerCatalogCursor {
	cloned := make(map[string]providerCatalogCursor, len(cursors))
	for source, cursor := range cursors {
		if paginatedProvider(source) && cursor.Initialized && cursor.Page >= 1 && cursor.Page <= 1000000 && len(cursor.Signature) <= 64 {
			cloned[source] = cursor
		}
	}
	return cloned
}

func (d *Downloader) providerCatalogSnapshot() map[string]providerCatalogCursor {
	d.providerCatalog.mu.Lock()
	defer d.providerCatalog.mu.Unlock()
	cursors := map[string]providerCatalogCursor{}
	for source, feed := range d.providerCatalog.feeds {
		if feed.cursor.Initialized {
			cursors[source] = feed.cursor
		}
	}
	return cursors
}

func (d *Downloader) restoreProviderCatalog(cursors map[string]providerCatalogCursor) {
	d.providerCatalog.mu.Lock()
	defer d.providerCatalog.mu.Unlock()
	if d.providerCatalog.feeds == nil {
		d.providerCatalog.feeds = map[string]*providerCatalogFeed{}
	}
	for source, cursor := range cloneProviderCatalog(cursors) {
		if d.providerCatalog.feeds[source] == nil {
			d.providerCatalog.feeds[source] = &providerCatalogFeed{cursor: cursor}
		}
	}
}

func (d *Downloader) fetchPagedProviderDramas(ctx context.Context, source string) ([]Drama, error) {
	if !paginatedProvider(source) || !sourceAllowed(ctx, source) {
		return nil, errors.New("该站源不可用")
	}
	d.providerCatalog.mu.Lock()
	if d.providerCatalog.feeds == nil {
		d.providerCatalog.feeds = map[string]*providerCatalogFeed{}
	}
	feed := d.providerCatalog.feeds[source]
	if feed == nil {
		feed = &providerCatalogFeed{}
		d.providerCatalog.feeds[source] = feed
	}
	d.providerCatalog.mu.Unlock()
	feed.loading.Lock()
	defer feed.loading.Unlock()
	d.providerCatalog.mu.Lock()
	cursor := feed.cursor
	d.providerCatalog.mu.Unlock()
	more, _ := ctx.Value(libraryMoreKey{}).(bool)
	var pages []int
	if !more || !cursor.Initialized {
		pages = append(pages, 1)
	}
	if cursor.Initialized && !cursor.Exhausted {
		if cursor.Page >= 1000000 {
			return nil, errors.New("站源分页已达到接口范围，已保留目录位置")
		}
		pages = append(pages, cursor.Page+1)
	}
	items := []Drama{}
	var failures []error
	for _, page := range pages {
		if err := ctx.Err(); err != nil {
			return items, errors.Join(append(failures, err)...)
		}
		rows, hasMore, err := d.fetchProviderCatalogPage(ctx, source, page, "", "")
		items = mergeSourceDramas(items, rows, nil, source)
		if err != nil {
			failures = append(failures, err)
			reportLibraryProgress(ctx, source, rows, nil, false)
			break
		}
		var ids []string
		for _, row := range rows {
			ids = append(ids, row.ID)
		}
		digest := sha256.Sum256([]byte(strings.Join(ids, "\n")))
		signature := hex.EncodeToString(digest[:])
		if page > 1 && (signature == cursor.Signature || hasMore && len(rows) == 0) {
			failures = append(failures, errors.New("站源分页未前进，已保留上次位置"))
			break
		}
		if !cursor.Initialized || page > cursor.Page {
			cursor = providerCatalogCursor{Page: page, Initialized: true, Exhausted: !hasMore, Signature: signature, UpdatedAt: time.Now()}
			d.providerCatalog.mu.Lock()
			feed.cursor = cursor
			d.providerCatalog.mu.Unlock()
		}
		reportLibraryProgress(ctx, source, rows, nil, false)
	}
	return items, errors.Join(failures...)
}

package app

import (
	"context"
	"errors"
	"regexp"
	"strconv"
	"strings"
)

const (
	sourceHuangju = "huangju"
	sourceYeguo = "yeguo"
	sourceDSD = "dsd"
)

var webProviderNumericID = regexp.MustCompile(`^[1-9][0-9]{0,17}$`)

type providerCategory struct {
	ID string `json:"id"`
	Name string `json:"name"`
}

func providerValueText(value any) string {
	return mapString(map[string]any{"value": value}, "value")
}

func webProviderInteger(value any, maximum int) (int, bool) {
	number, err := strconv.Atoi(providerValueText(value))
	return number, err == nil && number >= 0 && number <= maximum
}

func validProviderCategory(source, category string) bool {
	if category == "" {
		return true
	}
	if len(category) > 128 || strings.TrimSpace(category) != category || strings.ContainsAny(category, "|/\\\x00\r\n") {
		return false
	}
	switch source {
	case sourceHuangju:
		return category == huangjuNewestCategory || validHuangjuID(category) && !strings.HasPrefix(category, "@")
	case sourceYeguo:
		return validYeguoCategory(category)
	case sourceDSD:
		return webProviderNumericID.MatchString(category)
	}
	return false
}

func paginatedProvider(source string) bool {
	return source == sourceHuangju || source == sourceYeguo || source == sourceDSD
}

func (d *Downloader) fetchProviderCatalogPage(ctx context.Context, source string, page int, category, query string) ([]Drama, bool, error) {
	if !sourceAllowed(ctx, source) {
		return nil, false, errors.New("当前账号无权访问该站源")
	}
	switch source {
	case sourceHuangju:
		return d.fetchHuangjuCatalogPage(ctx, page, category, query)
	case sourceYeguo:
		return d.fetchYeguoCatalogPage(ctx, page, category, query)
	case sourceDSD:
		return d.fetchDSDCatalogPage(ctx, page, category, query)
	}
	return nil, false, errors.New("该站源不支持在线分页查询")
}

func (d *Downloader) fetchProviderDetail(ctx context.Context, source, id string) (Drama, []Chapter, error) {
	if !sourceAllowed(ctx, source) {
		return Drama{}, nil, errors.New("当前账号无权访问该站源")
	}
	switch source {
	case sourceHuangju:
		return d.fetchHuangjuDetail(ctx, id)
	case sourceYeguo:
		return d.fetchYeguoDetail(ctx, id)
	case sourceDSD:
		return d.fetchDSDDetail(ctx, id)
	}
	return Drama{}, nil, errors.New("该站源不支持详情查询")
}

