package app

import "strings"

func playbackHistoryIdentity(id string) (string, string, bool) {
	id = strings.TrimSpace(id)
	if id == "" || len(id) > 512 || strings.ContainsAny(id, "\x00\r\n\t /\\?#") {
		return "", "", false
	}
	if source, sourceID, ok := splitProviderDramaID(id); ok {
		return providerDramaID(source, sourceID), source, true
	}
	if !strings.Contains(id, ":") {
		return id, "cloudfront", true
	}
	return "", "", false
}
package app

import (
	"context"
	"errors"
	"math"
	"net/http"
	"reflect"
	"time"
)

const dramaRefreshRetryDelay = 5 * time.Minute

type dramaRefreshResult struct {
	DramaID    string `json:"dramaId"`
	Drama      Drama  `json:"drama"`
	RetryAfter int    `json:"retryAfter"`
	Warning    string `json:"warning,omitempty"`
}

type dramaRefreshCall struct {
	done    chan struct{}
	err     error
	retryAt time.Time
}

func (a *UIApp) handleDramaRefresh(w http.ResponseWriter, r *http.Request) {
	var input struct {
		DramaID string `json:"dramaId"`
	}
	if !readPlaybackRequest(w, r, &input) || !a.requireDramaSources(w, r, []string{input.DramaID}) {
		return
	}
	source, id, valid := splitProviderDramaID(input.DramaID)
	if !valid || len(input.DramaID) > 512 || !supportsSortMetadata(Drama{Source: source}) {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "剧集资料更新参数无效"})
		return
	}
	input.DramaID = providerDramaID(source, id)
	a.mu.Lock()
	drama := a.dramaForRefreshLocked(input.DramaID)
	a.mu.Unlock()
	if drama.ID == "" {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": "剧库中没有该剧集"})
		return
	}
	result, err := a.refreshDramaMetadata(r.Context(), drama)
	if r.Context().Err() != nil {
		return
	}
	if err != nil {
		writeJSON(w, http.StatusTooManyRequests, map[string]string{"error": "资料更新繁忙，可稍后重新打开剧集"})
		return
	}
	writeJSON(w, http.StatusOK, result)
}

func (a *UIApp) dramaForRefreshLocked(id string) Drama {
	for _, drama := range a.dramas {
		if drama.ID == id {
			return drama
		}
	}
	return Drama{}
}

func (a *UIApp) dramaRefreshResultLocked(id string, call *dramaRefreshCall) dramaRefreshResult {
	result := dramaRefreshResult{DramaID: id, Drama: a.dramaForRefreshLocked(id), RetryAfter: max(1, int(math.Ceil(time.Until(call.retryAt).Seconds())))}
	if call.err != nil {
		result.Warning = "部分资料暂未更新，已保留原有信息，可稍后再次打开剧集重试"
	}
	return result
}

func (a *UIApp) refreshDramaMetadata(ctx context.Context, drama Drama) (dramaRefreshResult, error) {
	if err := ctx.Err(); err != nil {
		return dramaRefreshResult{}, err
	}
	now := time.Now()
	a.mu.Lock()
	if call := a.dramaRefreshes[drama.ID]; call != nil && (call.retryAt.IsZero() || now.Before(call.retryAt)) {
		a.mu.Unlock()
		select {
		case <-ctx.Done():
			return dramaRefreshResult{}, ctx.Err()
		case <-call.done:
			if errors.Is(call.err, context.Canceled) && ctx.Err() == nil {
				return a.refreshDramaMetadata(ctx, drama)
			}
			a.mu.Lock()
			result := a.dramaRefreshResultLocked(drama.ID, call)
			a.mu.Unlock()
			return result, nil
		}
	}
	pending := 0
	for id, call := range a.dramaRefreshes {
		if call.retryAt.IsZero() {
			pending++
		} else if !now.Before(call.retryAt) {
			delete(a.dramaRefreshes, id)
		}
	}
	if pending >= 8 || len(a.dramaRefreshes) >= 256 {
		a.mu.Unlock()
		return dramaRefreshResult{}, errors.New("剧集资料更新请求过多")
	}
	if a.dramaRefreshes == nil {
		a.dramaRefreshes = make(map[string]*dramaRefreshCall)
		a.dramaRefreshSlots = make(chan struct{}, 1)
	}
	call := &dramaRefreshCall{done: make(chan struct{})}
	a.dramaRefreshes[drama.ID] = call
	slots := a.dramaRefreshSlots
	a.mu.Unlock()
	work, cancel := context.WithTimeout(context.WithValue(ctx, backgroundCatalogKey{}, true), 35*time.Second)
	defer cancel()
	var patch Drama
	var err error
	select {
	case <-work.Done():
		err = work.Err()
	case slots <- struct{}{}:
		patch, err = a.downloader.fetchDramaMetadata(work, drama)
		<-slots
	}
	if patch.ID != "" && patch.ID != drama.ID {
		patch = Drama{}
		err = errors.New("详情返回了其他剧集")
	}
	changed := false
	a.mu.Lock()
	if ctx.Err() == nil && patch.ID == drama.ID {
		for index, current := range a.dramas {
			if current.ID != drama.ID {
				continue
			}
			if err == nil {
				patch.SortMetadata = completedDramaMetadata(current)
			}
			updated := mergeRefreshedDrama(patch, current, drama)
			if !reflect.DeepEqual(updated, current) {
				a.dramas[index] = updated
				a.libraryDirty = true
				a.libraryRevision++
				changed = true
			}
			break
		}
	}
	a.mu.Unlock()
	if changed {
		a.persistLibrary()
	}
	if err != nil && ctx.Err() == nil {
		a.downloader.recordDiagnostic(diagnosticEvent{Event: "drama.metadata_failed", Source: dramaProvider(drama), DramaID: drama.ID, Message: a.redactError(err)})
	}
	a.mu.Lock()
	call.err, call.retryAt = err, time.Now().Add(dramaRefreshRetryDelay)
	if ctx.Err() != nil {
		call.err = ctx.Err()
		delete(a.dramaRefreshes, drama.ID)
	}
	result := a.dramaRefreshResultLocked(drama.ID, call)
	close(call.done)
	a.mu.Unlock()
	return result, ctx.Err()
}

func mergeRefreshedDrama(patch, current, previous Drama) Drama {
	updated := mergeDramaMetadata(patch, current)
	if current.SortMetadata != nil && (previous.SortMetadata == nil || current.SortMetadata.CheckedAt.After(previous.SortMetadata.CheckedAt)) {
		updated = mergeDramaMetadata(current, patch)
	}
	if current.Title != previous.Title || current.Name != previous.Name {
		updated.Title, updated.Name = current.Title, current.Name
	}
	if bestDramaCover(current) != bestDramaCover(previous) {
		updated.Cover, updated.CoverURL = current.Cover, current.CoverURL
	}
	normalizeDramaCover(&updated)
	return updated
}

func completedDramaMetadata(drama Drama) *sortMetadataState {
	state := sortMetadataState{Version: dramaSortMetadataVersion(drama), CheckedAt: time.Now(), CoverChecked: dramaProvider(drama) == sourceHongguo, VIPChecked: dramaProvider(drama) == sourceHuangdou}
	if drama.SortMetadata != nil {
		state.Pending = drama.SortMetadata.Pending
	}
	return &state
}
package app

import (
	"errors"
	"fmt"
	"net/http"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

type followingView struct {
	followingEntry
	TotalEpisode int `json:"totalEpisode"`
	NewEpisodes  int `json:"newEpisodes"`
}

func followingEpisodeCount(drama Drama) int {
	for _, value := range []any{drama.TotalEpisode, drama.TotalEpisodeSnake, drama.ChapterCount, drama.ChapterCountSnake, drama.EpisodeCount, drama.EpisodeCountSnake, drama.Total, drama.Episodes} {
		count, err := strconv.Atoi(strings.TrimSpace(fmt.Sprint(value)))
		if err == nil && count > 0 && count <= 10000 {
			return count
		}
	}
	return 0
}

func followingDramaEntry(drama Drama) followingEntry {
	id, source, valid := playbackHistoryIdentity(drama.ID)
	if !valid {
		return followingEntry{}
	}
	return followingEntry{DramaID: id, Source: source, Title: followingText(drama.DisplayTitle(), 4096), Category: followingText(firstNonEmpty(drama.CategoryName, drama.CategoryNameSnake, drama.Category, drama.TypeName, drama.SortName), 512), KnownEpisodes: followingEpisodeCount(drama)}
}

func followingText(value string, limit int) string {
	value = strings.ToValidUTF8(strings.TrimSpace(value), "")
	if len(value) > limit {
		value = value[:limit]
		for !utf8.ValidString(value) {
			value = value[:len(value)-1]
		}
	}
	return value
}

func (app *UIApp) followingMetadata(ids []string) map[string]followingEntry {
	result := make(map[string]followingEntry, len(ids))
	if len(ids) == 0 {
		return result
	}
	wanted := make(map[string]bool, len(ids))
	for _, id := range ids {
		wanted[id] = true
	}
	selected := make([]Drama, 0, len(ids))
	app.mu.Lock()
	for _, drama := range app.dramas {
		if wanted[drama.ID] {
			selected = append(selected, drama)
		}
	}
	app.mu.Unlock()
	for _, drama := range selected {
		entry := followingDramaEntry(drama)
		if entry.DramaID != "" {
			result[entry.DramaID] = entry
		}
	}
	return result
}

func (app *UIApp) handleFollowing(writer http.ResponseWriter, request *http.Request) {
	if request.Method == http.MethodPost {
		app.handleFollowingUpdate(writer, request)
		return
	}
	if !playbackRequestAllowed(writer, request, http.MethodGet) {
		return
	}
	viewer := requestViewer(writer, request)
	if viewer == nil {
		return
	}
	entries, err := viewer.followingStore().list()
	if err != nil {
		writeJSON(writer, http.StatusInternalServerError, map[string]string{"error": "无法读取追剧清单：" + publicError(err).Error()})
		return
	}
	ids := make([]string, 0, len(entries))
	for _, entry := range entries {
		ids = append(ids, entry.DramaID)
	}
	known := app.followingMetadata(ids)
	result := make([]followingView, 0, len(entries))
	for _, entry := range entries {
		if !dramaAllowed(request.Context(), entry.DramaID, entry.Source) {
			continue
		}
		view := followingView{followingEntry: entry, TotalEpisode: entry.KnownEpisodes}
		if current, exists := known[entry.DramaID]; exists {
			view.Title = current.Title
			view.Category = current.Category
			if current.KnownEpisodes > 0 {
				view.TotalEpisode = current.KnownEpisodes
				if entry.KnownEpisodes > 0 && current.KnownEpisodes > entry.KnownEpisodes {
					view.NewEpisodes = current.KnownEpisodes - entry.KnownEpisodes
				}
			}
		}
		result = append(result, view)
	}
	writeJSON(writer, http.StatusOK, map[string]any{"data": result, "limit": followingLimit})
}

func (app *UIApp) handleFollowingUpdate(writer http.ResponseWriter, request *http.Request) {
	var input struct {
		DramaID     string `json:"dramaId"`
		Saved       *bool  `json:"saved"`
		Completed   *bool  `json:"completed"`
		Acknowledge bool   `json:"acknowledge"`
	}
	if !readPlaybackRequest(writer, request, &input) {
		return
	}
	id, _, valid := playbackHistoryIdentity(input.DramaID)
	if !valid || input.Saved == nil && input.Completed == nil && !input.Acknowledge {
		writeJSON(writer, http.StatusBadRequest, map[string]string{"error": "追剧操作或剧集 ID 无效"})
		return
	}
	viewer := requestViewer(writer, request)
	if viewer == nil {
		return
	}
	if !app.requireDramaSources(writer, request, []string{id}) {
		return
	}
	metadata := app.followingMetadata([]string{id})[id]
	if metadata.DramaID == "" {
		if history, exists := viewer.playbackHistory().get(id); exists {
			metadata = followingEntry{DramaID: id, Source: history.Source, Title: followingText(history.Title, 4096), KnownEpisodes: history.Total}
		}
	}
	entry, err := viewer.followingStore().update(id, func(previous followingEntry, exists bool) (followingEntry, error) {
		if !exists {
			if metadata.DramaID == "" {
				return followingEntry{}, errFollowingUnknown
			}
			previous = metadata
			previous.AddedAt = time.Now()
		}
		if metadata.DramaID != "" {
			previous.Title, previous.Category = metadata.Title, metadata.Category
			if metadata.KnownEpisodes > 0 && (input.Acknowledge || input.Completed != nil && *input.Completed || previous.KnownEpisodes == 0) {
				previous.KnownEpisodes = metadata.KnownEpisodes
			}
		}
		if input.Saved != nil {
			previous.Saved = *input.Saved
		}
		if input.Completed != nil {
			previous.Completed = *input.Completed
		}
		previous.UpdatedAt = time.Now()
		return previous, nil
	})
	if err != nil {
		status := http.StatusInternalServerError
		if errors.Is(err, errFollowingUnknown) {
			status = http.StatusNotFound
		} else if errors.Is(err, errFollowingLimit) {
			status = http.StatusConflict
		}
		writeJSON(writer, status, map[string]string{"error": "追剧操作未保存：" + publicError(err).Error()})
		return
	}
	app.notifyEmbySync()
	writeJSON(writer, http.StatusOK, map[string]any{"ok": true, "entry": entry})
}

