	store := app.browserViewers().accountStore()
	store.mu.Lock()
	defer store.mu.Unlock()
	if store.err != nil {
		return false
	}
	for _, account := range store.state.Accounts {
		if account.ID == owner {
			return !account.onlineOnly() && dramaAllowed(withSourceScope(context.Background(), account), dramaID, "")
		}
	}
	return false
}
