		} else {
			media.URL = parseDataHLS(body, pageURL)
		}
		d.providerMu.Lock()
		if preferred := d.providerHosts[chapter.Source]; preferred != "" {
			media.Referer = preferred + "/"
		}
		d.providerMu.Unlock()
