	if asset.playlist {
		extension = ".m3u8"
	} else if len(asset.body) > 0 {
		extension = ".key"
	}
	asset.extension = extension
	local := proxy.base + strconv.Itoa(len(proxy.assets)+1) + extension
	if proxy.query != "" {
		local += "?" + proxy.query
