			if err != nil || len(body) > providerMaxBodyBytes {
				proxy.fail(writer, request, errors.New("读取 HLS 播放列表失败或内容过大"))
				return
			}
			asset.playlist = true
			if response.Request != nil && response.Request.URL != nil {
				asset.remote = response.Request.URL.String()
			}
