			if strings.HasPrefix(line, "#EXT-X-STREAM-INF:") {
				nextPlaylist = true
				continue
			}
			if !strings.HasPrefix(line, "#") {
				if !resolve(line, nextPlaylist) {
					return false
				}
				nextPlaylist = false
				continue
			}
			for _, tag := range []string{"#EXT-X-MEDIA:", "#EXT-X-I-FRAME-STREAM-INF:", "#EXT-X-KEY:", "#EXT-X-SESSION-KEY:", "#EXT-X-MAP:"} {
