	}
	if patch.ID != "" && patch.ID != drama.ID {
		patch = Drama{}
		err = errors.New("详情返回了其他剧集")
	}
	changed := false
	a.mu.Lock()
	if ctx.Err() == nil && patch.ID == drama.ID {
		for index, current := range a.dramas {
