					cancel()
					continue
				}
				status, err := a.checkNetworkResource(probeCtx, http.MethodGet, target.endpoint, imageReferer(target.endpoint), false)
				cancel()
				results[index] = networkCheckResult{Name: target.name, Status: status, Error: a.redactError(err)}
			}
		}()
	}
